window.LANGPACK.put("la","words",{"a":[["audiō","v.听见","",""],["amīcus","n.朋友","","形容词义「友好的」；名词义「朋友」，女性用 amīca。"],["aqua","n.水","",""],["aurum","n.黄金","","亦指金制品、金币；金的光泽义较少见。"],["absum","v.不在","","不规则动词；也指相距、远离、缺席"],["aspiciō","v.看见","","偏重朝某处看、注视，比 videō 更强调「看向」"],["anima","n.呼吸|n.生命","|","指吸入呼出的气息；更常见的意思是「灵魂、生命」。spiritus 偏指呼吸这一动作。；比 animus 更偏「生命之气」；还有灵魂、风、气息等义。"],["auxilium","n.帮助","","复数 auxilia 指援军"],["abeō","v.离开","",""],["antīquus","adj.古老的","",""],["ārdeō","v.燃烧","","转指情感炽烈、热切渴望。"],["amplus","adj.大的","","也指丰盛的、显赫的"],["abscēdō","v.离开","",""],["adventus","n.来到","","第四变格阳性；到来、抵达（教会拉丁的「降临节」不取）"],["afflō","v.吹拂","","向…吹气、吹到；也指（火、光、气）触及。"],["aspīrō","v.吹拂","","L&S I.A：to breathe or blow upon；Verg. A. 1,694「aspirans complectitur」；Cic. N.D. 2,55,136"],["arbor","n.树","",""],["aethēr","n.天空","","指高处清澈的上层空气、天空。"],["adminiculum","n.帮助","","本义支柱、支撑物（葡萄架），引申辅助、帮助"],["aetherius","adj.天空的","","「以太的、天上的」，诗体色彩；比「天空的」更偏「上层高空、天界」。"],["alimentum","n.食物","","偏「营养、养分、给养」，法学上指赡养费；诗体多用复数 alimenta。"],["altum","n.海","","中性名词化形容词，指深海、外海，也指高处、天穹；常见 in altum（驶入大海）。"],["ambulō","v.行走","","指散步式的行走，比 vādō 缓"],["amplitūdō","n.宽广","","指空间的广度、规模；引申为宏大、威严"],["anhēlitus","n.呼吸","","本义偏「喘息、气喘」，也泛指呼吸、呼出的气。"],["abitiō","n.离开（古）","","早期拉丁用词；见普劳图斯与泰伦提乌斯喜剧。"],["absistō","v.离开","","较罕用；西塞罗不用"],["adhinniō","v.嘶鸣","","L&S I：to neigh to or after；Ov. Rem. Am. 634"],["aequoreus","adj.海的（诗）","","只见于诗体的「海的」，如 aequoreus rex（海王 Neptunus）。"],["aethra","n.天空（诗）","","诗体词，指晴朗的天空；与 aethēr 近义。"],["algor","n.寒冷","","指身体感到的寒冷"],["algus","n.寒冷（古）","","早期名词，常见于夺格 algū；词典对主格及性别传统有分歧，现按阳性第四变格词头。"],["alimōnia","n.食物","","古旧词，意为营养、食物；日常用 alimentum、cibus。"],["anīlis","adj.老妇的","","L&S：of an old woman；贬义「老太婆似的」（Cic. Tusc. 1,39,93；Hor. S. 2,6,77）"],["aprīcus","adj.向阳的","","指受阳光照射、日照充足的地方"],["aquārius","adj.水的","","形容词义「水的」；更常作名词：提水人、水道管理员、宝瓶座（Cic. Arat.）。"],["auxiliāris","adj.帮助的","","形容词：有助的、提供援助的；也指辅助的、援军的"],["auxilior","v.帮助","","异态动词，与与格连用；较罕用"],["accipiō","v.接受","",""],["aestās","n.夏天","",""],["aetās","n.年龄|n.时代","|","aurea aetās「黄金时代」。"],["ager","n.田地","",""],["agmen","n.行军队伍","",""],["agō","v.驱赶|v.做","","侧重「做、进行」某事，不留下成品；制作东西用 faciō。quid agis? 你在做什么、近来如何。"],["amnis","n.大河","",""],["annus","n.年","",""],["āra","n.祭坛","","ārae et focī「祭坛与炉灶」，喻家园。"],["ars","n.技艺","",""],["aura","n.微风","",""],["auris","n.耳朵","",""],["autumnus","n.秋天","",""],["animus","n.心灵","","理性与情感所在；也指勇气、意图。"],["amor","n.爱","","也指所爱之人、欲念；大写 Amor 是爱神。"],["amō","v.爱","","也有「喜欢、爱好」义（+不定式），与 dīligō 的珍重之爱不同。"],["aeternus","adj.永恒的","","强调「超越时间的永恒」；比 sempiternus 更哲学。"],["aevum","n.永恒","","永恒之外，常指一生、一世、时代；in aevum「永远」。"],["absconditus","adj.秘密的","","偏「隐藏起来的」，也可作「秘而不宣」。"],["appetō","v.追求","","另有「攻击、临近」义。"],["ārdor","n.炽热","","本义火焰、灼热；转指热情与渴望。"],["abstrūsus","adj.隐藏的","","也可指道理深奥难懂（Cic. Ac. 2,10,30），或人深藏不露（Tac.）。"],["adamō","v.深爱","","L&S：to love truly, earnestly, deeply（Cic. Mil. 32,87；Nep. Dion 2,3），亦作迷恋"],["adoptō","v.选择","","本义是「选来作为己有」，最常见的用法是「收养、采纳」；「选择」为 L&S 首义，但带「选为己用」色彩。"],["adulēscentia","n.青春","","指约十五到三十岁的青年时期，不是「幼年」。"],["adversor","v.抵抗","","偏「持异议、反对」；用外在行动抵抗是 resistō、obsistō。"],["aemulātiō","n.竞争心","","好义为力争上游，贬义为嫉妒。"],["aemulor","v.争胜","","异相动词；力图赶上或胜过，贬义时指嫉妒。"],["aemulus","adj.争胜的","","与人较量、力图比肩；贬义时指嫉妒的。"],["affectō","v.追求","","常含「做作、刻意」意味（贬义时「谋求、攫取」）。"],["amātor","n.爱慕者","","爱好者、爱慕者；也指情人。"],["arcānus","adj.秘密的","","偏「隐秘的、不外泄的」；也有「守口如瓶的」义（Plaut.）。"],["asservō","v.守护","","偏「看管、妥善保存」（常指看押之物）。"],["aucupor","v.捕鸟","","异相动词；转指伺机猎取。"],["aveō","v.渴望","","同形的 avēre（祝安、ave! 问候语）是另一个词，这里取「渴望」义；多接不定式，偏书面。"],["aviditās","n.渴望","","强烈的渴求；用于钱财则指贪婪（II.A），+动名词属格：aviditās legendī 求知若渴。"],["aegritūdō","n.悲伤","","西塞罗哲学用语，指心灵之痛、忧伤；本义有疾病，后期也指身体病。"],["aenigma","n.谜语","","难解的隐晦之物；修辞上指晦涩的讽喻。"],["aetātula","n.稚龄","","L&S：a youthful, tender age（Plaut. Ps. 1,2,40；Cic. Fin. 5,20,55）"],["affectātiō","n.追求","","常贬义，指「刻意求取」「做作」（英语 affectation）；中性的「追求」义多见于 Sen.、Tac.。"],["amoenitās","n.宜人之美","","多指景致、地方的秀丽宜人"],["animula","n.小灵魂","","指小词：小小的灵魂、小命；Hadr. ap. Hist. Aug. 25；Cic. Fam. 4,5,11"],["appetentia","n.渴望","","常带属格宾语：adpetentia gloriae 对荣誉的渴望；比 cupiditās 罕见。"],["appetītiō","n.渴望","","西塞罗用来译斯多葛的「冲动、欲求」（ὁρμή），偏哲学用语；也指食欲。"],["arcānum","n.秘密","","常复数 arcāna（隐秘之事、神秘之物）。"],["assēnsus","n.赞同","","诗中转指回声。"],["āvium","n.荒野","","实际多用复数 āvia（无路的荒僻处）；单数 āvium 少见。"],["absentia","n.缺席","","指人不在场；也可指缺乏某物。"],["aciēs","n.战阵|n.锋刃","|","也指目光的锐利。"],["aequor","n.海面","","诗中常直接指大海。"],["aeternitās","n.永恒","",""],["amīcitia","n.友谊","","西塞罗有专论《论友谊》（Laelius de amicitia）。"],["arma","n.武器","","只用复数（中性复数）。"],["aurōra","n.黎明","","多见于诗；拟人为黎明女神 Aurōra。"]],"b":[["bonus","adj.好的","","比较级 melior，最高级 optimus"],["brevis","adj.短的","","指长度、时间、深度短浅；与 parvus（体积小）有别"],["beneficium","n.恩惠","","指施予的好处、善举；也指恩赐的官职、权利"],["barbarus","adj.异族的|n.蛮族人","","原指非希腊罗马的；引申为未开化的、粗野的。；多用复数 barbarī 泛指外族。"],["bibō","v.喝","",""],["barathrum","n.深渊（诗）","","多用于诗，也可指冥界、无底深渊；另有「贪吞之腹」的讽刺义。"],["beātus","adj.幸福的","","beāta vīta 幸福生活；教会拉丁里指「蒙福的」。"],["bellum","n.战争","","古体 duellum；bellum gerere 作战。"],["benedīcō","v.祝福（教）","","古典作家分写 bene dīcere「说好话」；教会拉丁合成一词，指祝福、颂赞。"]],"c":[["corpus","n.身体","",""],["caelum","n.天空","","也指气候、天气。"],["cursus","n.奔跑","","名词（第四变格）：奔跑；更常用义是路线、航程、进程"],["comes","n.同伴","","同行的伙伴、随从；阴阳同形。"],["currō","v.奔跑","",""],["cernō","v.看见","","偏重辨认出、看清；本义是分开、筛选"],["concēdō","v.让步","","多与与格连用，指退让、屈服、承认、准许；本义的「离去」较少见"],["cibus","n.食物","",""],["caleō","v.温暖","","指（物体）发热、暖；也喻激动、炽热"],["coniciō","v.投掷","","亦指推测、断定。"],["cursō","v.奔跑","","curro 的频繁式，多指来回跑动"],["caelestis","adj.天空的","","「天上的、属天的」，也指神圣的、神的；名词复数 caelestēs 指诸神。"],["calor","n.温暖","","偏重热度；也喻激情、热情"],["cibāria","n.食物","","中性复数，指口粮、给养，偏「定量的食物」。"],["cōdex","n.书","","指装订成册的书（册子本），也指账簿；本义是树干"],["cōnspiciō","v.看见","","偏重望见、注意到"],["cubīle","n.床","","指睡觉之处，也指婚床、兽窝；比 lectus 更偏「卧处」。"],["curriculum","n.赛跑","","也指跑道、赛车；引申为人生的历程；现代「课程」义是后起义"],["caldor","n.温暖（古）","","古代前、后古典时期用词，常规同义词为 calor。"],["camera","n.拱顶","","建筑的拱形顶、穹窿。"],["cardiacus","adj.心脏的","","L&S 释为「心或胃的」，古典例子多指心口、胃部之病（cardiacus morbus）。"],["cibārius","adj.食物的","","「食物的、供食用的」，也指粗劣的（cibarius panis 粗面包）。"],["cibātus","n.食物","","较罕用，指食物、给养；日常用 cibus。"],["collūsor","n.玩伴","","一起玩耍或游戏的伙伴；另有法律义「串通者」（晚期）。"],["commentātiō","n.学习","","名词：钻研、专心演练；也指论著"],["conclāve","n.房间","","指能上锁的房间，也指餐厅、兽栏。"],["cōnscrīptiō","n.撰写（罕）","","指撰写、编写，也可指书面作品；不是现代征兵概念。"],["cōnspicor","v.看见","","偏重瞥见、望见；异态动词；西塞罗、维吉尔不用，见于普劳图斯、凯撒"],["corporālis","adj.身体的","","「身体的、肉体的」，也指有形体的；多见于 Seneca 以后的散文。"],["culīna","n.厨房","","转指饭食。"],["campus","n.平原","","Campus Mārtius「战神广场」。"],["capiō","v.抓住","","arma capere 拿起武器。"],["caput","n.头","","也引申为首领、首要、源头、首都。"],["castra","n.军营","","中性复数形式、单数意义；castra pōnere 扎营。清单词 castrum（单数「堡垒」较少用）以此条代收。"],["cāsus","n.坠落|n.偶然","|","cāsū「偶然地」。语法上也指「格」。"],["causa","n.原因|n.案件","|","夺格 causā 后置作「为了」（如 honōris causā），是另一用法。；causam agere 办案、辩护。"],["cīvitās","n.国家|n.公民权","|",""],["classis","n.舰队","","本义是罗马公民的等级。"],["coma","n.头发","","诗中也指树叶。"],["coniūnx","n.配偶","","阴阳通用，多指妻子。"],["cōnsilium","n.计划|n.建议","|",""],["cōpia","n.丰富|n.兵力","|","此义多用复数 cōpiae。"],["crās","adv.明天","",""],["crīmen","n.指控","","诗中也指罪行。"],["currus","n.战车","",""],["crēdō","v.信任","","常义是「相信」；+与格（人）则是「信任、托付」，原义是「借出」。"],["cadūcus","adj.易逝的","","指不能久存、转瞬即逝；Cicero 常与 fragilis 并用（fragile et caducum）。"],["captō","v.追求","","喻义「谋求、讨好」，如 plausūs captāre（博取掌声）。"],["compāreō","v.显现","","指变得明显、出现在眼前。"],["cupiō","v.渴望","","强度偏自然的、压不住的欲望（对比 volō 意愿、optō 选择性的愿望）。"],["cupīdō","n.渴望","","也指贪欲、情欲；大写 Cupīdō 是爱神。"],["cāritās","n.爱","","本义「昂贵」，转义「亲爱、敬爱之情」；教会拉丁里是「仁爱」，这里取古典义。"],["coalēscō","v.结合","","本义指（植物、伤口等）长合；转义为联合、结合。不是化学上的聚合。"],["cōnfīdō","v.信任","","半异相动词（完成时 cōnfīsus sum），+与格/奪格「信赖、倚仗」；比 crēdō 更强调有把握的信赖。"],["cōnfīnium","n.边界","","多指两地相接之处（接壤、交界），比 terminus、līmes 更偏「交界带」。"],["congredior","v.相遇","","既可「会面」也可「交锋」，看上下文。"],["cōnsector","v.追求","","偏「紧追不舍、热切追求」。"],["cōnsenēscō","v.衰老","","原义「一同变老、变老」，转义「衰败、荒废」；常带 in+奪格（在…中老去）。"],["cupidus","adj.渴望的","","+属格（cupidus videndī 渴望见到）；也指贪婪、偏私。"],["cālīginōsus","adj.雾蒙蒙的","","L&S 注明「rare, but class.」。"],["chaos","n.混沌","","Chaos 亦为冥界神名（Verg. A. 4,510），梗图里取「混沌」最稳。"],["clandestīnus","adj.秘密的","","偏「暗中进行的」（见不得人的）。"],["commiserēscō","v.怜悯（古）","","前古典用语，常用非人称：+宾格（人）+属格（事）；古典时期多用 misereor。"],["commiseror","v.怜悯","","异相动词；多指为他人不幸而哀叹、激起怜悯；比 misereor 更偏表达。"],["crepusculum","n.暮色","","中性；诗语或帝国时期散文多用。"],["crystallinus","adj.水晶的","","指水晶制成的（器皿）；也作名词 crystallina 指水晶杯。"],["cadō","v.落下","","也指战死、日落、失败。"],["caedēs","n.杀戮","",""],["carmen","n.诗歌","","也指歌声、咒语、神谕。"],["concordia","n.和睦","","拟人为和睦女神 Concordia。"],["cūra","n.关怀|n.忧虑","|","诗中常用复数 cūrae 指心事、相思之苦。"]],"d":[["dō","v.给予","","不规则的第一变格动词（dare）"],["domus","n.家","",""],["discō","v.学习","",""],["discēdō","v.离开","","也有分开、偏离义"],["dēcēdō","v.离开","","也指让路、卸任、死去、减退"],["dēliciae","n.快乐","","多用复数；也指宠儿、心肝、奢侈享受"],["dīvum","n.天空","","主要用于 sub dīvō（露天、在天空下）、sub dīvum 等介词短语。"],["dēcidō","v.掉落","","L&S I：to fall down or off（dēcidō，cad-）；与 dēcīdō「切断、决定」同形"],["dēveniō","v.来到","","来到某处，常含途经后终于到达"],["dictiō","n.说话","","名词：说话、陈述；修辞与法律语境常指发言、辩护、措辞"],["domesticus","adj.家庭的","","既指家里的、家庭的，也指本国的、国内的、驯养的。"],["datiō","n.给予","","行为名词：给予、分配；较少见"],["dēcessus","n.离开","","名词：离去；也指官员卸任、潮退、死亡"],["dēlectātiō","n.快乐","","指赏心悦目的乐趣、消遣"],["dēmigrō","v.离开","","多指迁出、搬离居住地"],["dīgredior","v.离开","","异态动词；也指离题、偏离"],["dēbeō","v.欠|v.应该","","接不定式。"],["dēnique","adv.最后","",""],["dīcō","v.说","",""],["diēs","n.日子","","也指白昼、约定的日期。"],["diū","adv.很久","",""],["dominus","n.主人","",""],["dōnum","n.礼物","",""],["dūcō","v.带领","","也指拉、引；uxōrem dūcere 娶妻。"],["dux","n.首领","","军事上指统帅、将领。"],["doleō","v.悲伤","","本义身体痛，也指为…悲痛；非人称/+宾格「为…伤心」。"],["dēsīderō","v.渴望","","也指「想念、缺少」；西塞罗常用于思念不在的人。"],["dīligō","v.爱","","偏「珍重、器重」之爱，比 amō 更含理性与敬重，不含情欲（Cic. Lael.）。"],["dēligō","v.选择","","指第三变位的 dēligere（挑选）；同形的 dēligāre（捆绑）是另一个词。"],["dēsīderium","n.思念","","带属格：desiderium Athenārum 对雅典的思念；亦作爱称「我的心肝」。"],["dēspondeō","v.承诺","","更常指「许婚、订婚」；一般「承诺」少见，宜归在「承诺」概念下作书面用法。"],["dīlēctiō","n.爱（教）","","教会拉丁语；常译希腊语 agápē，指珍重之爱。"],["dulcēdō","n.甜美","","本义甜味；引申为令人愉悦的魅力"],["dēcrepitus","adj.衰老的（古）","","多指年迈体衰的老人（前古典用语为主）。"],["dēlēctus","n.选择","","本义「挑选」，另有「征兵」义（dēlectum habēre）；第四变位，属格 dēlectūs。"],["dēsūmō","v.选择","","较少见，多为「为自己挑出、选取」。"],["dīgressus","n.离别","","第四变格阳性名词，勿与 digredior 的分词混淆。"],["deus","n.神","","复数主格常作 dī；基督教拉丁指上帝。"],["discessus","n.离去","",""],["dolor","n.痛苦","","身体的疼痛和心里的悲痛都可用。"]],"e":[["exspectō","v.等待","","也有期待、盼望义"],["exeō","v.离开","","不规则动词，eō 的复合词"],["edō","v.吃","","「吃」的动词 edō 变位不规则（edō, edere/esse, ēdī, ēsum）；别与 ēdō「发出」混。"],["ēgredior","v.离开","","异态动词；本义走出、出去"],["emō","v.购买","","本义是取得，常用义是购买"],["ēsca","n.食物","","也指饵、诱饵（转义）。"],["excēdō","v.离开","","本义走出、离去；也可指超出、越界"],["exitus","n.离开","","名词：离去；常用义还有出口、结局"],["ēmptiō","n.购买","","行为名词：购买；也指所购之物、买卖契约"],["excessiō","n.离开（教）","","教会拉丁语及晚期用语；也婉指去世。古典常用 excessus。"],["excessus","n.离开|n.死亡","|","名词：离去；常指离世（excessus e vita）；本义「离开」，转指「逝世」（excessus vītae）；后期单用即「死」。"],["edūlia","n.食物","","中性复数名词（edūlia, -ium），指可吃的东西；单数 edūlium 只见于晚期。"],["eō","v.去","","不规则动词，不定式 īre；命令式 ī!「去吧」。"],["equus","n.马","","阴性 equa 指母马。"],["ēripiō","v.夺走","","也指救出（ēripere aliquem ex perīculō）。"],["exemplum","n.范例","",""],["exercitus","n.军队","",""],["extrēmus","adj.最远的|adj.最后的","","如 extrēma hōra 最后时刻。"],["ēligō","v.选择","",""],["ēchō","n.回声","","ēchō 也是山林仙女 Echō 之名（Ov. M. 3）。"],["ēlābor","v.溜走","","异相动词；滑脱、逃脱。"],["exsequor","v.追求","","最常义是「执行、贯彻、叙述」；「追求」取其「追随至终」之义，较弱。"],["efflōreō","v.绽放（教）","","教会拉丁语；古典常用 efflōrēscō、flōreō。"],["ēloquium","n.口才（诗）","","诗体用语，指口才、辞令、言辞之美"],["erēmus","n.荒野（教）","","教会拉丁语；希腊借词，指荒漠、旷野，隐修士所居。"],["ēvānēscō","v.消逝","",""]],"f":[["fūnus","n.葬礼","","诗中也转指死亡，尤指横死。"],["fessus","adj.疲倦的","","指累了、疲乏的（状态）"],["flōs","n.花","",""],["fīlius","n.儿子","","男性后代；泛指孩子们用 līberī。"],["foris","n.门","","多用复数 forēs（两扇门）；同形 foris 作副词是「在外面」，另一个词。"],["frīgus","n.寒冷","","第三变格中性；也指寒战、冷淡"],["flūmen","n.河流","","指河流、水流；Caesar 常用。"],["familia","n.家庭","","首义是一户之内的人（含奴仆），也指家族、家庭。"],["familiāris","adj.家庭的","","「家庭的、家里的」，也有「亲近的、熟悉的」；名词 familiāris 是亲信、密友。"],["fluvius","n.河流","","指河流；凯撒不用此词，常用 flūmen。"],["fretum","n.海峡","","诗中泛指海。"],["frīgidus","adj.寒冷的","","冷、凉；也喻冷淡、乏味"],["faciēs","n.外貌","",""],["faciō","v.做","","侧重「制作、造成」，被动用 fīō。"],["fax","n.火炬","","诗中也指婚礼火炬、爱火。"],["fēmina","n.女人","",""],["fenestra","n.窗","",""],["ferō","v.携带|v.忍受","","不规则动词。"],["ferrum","n.铁|n.剑（诗）","|","以「铁」代指刀剑，ferrō et ignī「以刀与火」。"],["fīō","v.变成|v.发生","","faciō 的被动；完成时用 factus sum。；fit ut … 「结果是……」。"],["flūctus","n.波浪","",""],["fōrma","n.形状|n.美貌","|",""],["fortāsse","adv.也许","",""],["frāter","n.兄弟","","教会拉丁也称修士、教友。"],["fuga","n.逃跑","","也指流放。"],["fortūna","n.命运","","本义运气、机运（也是女神名）；「命运」取其「机运所定」义。"],["fātum","n.命运","",""],["fugiō","v.逃跑","","也指时光飞逝。"],["fidēs","n.信任","","「信任」取 fidem habēre alicui（信任某人）一类用法；也有信誉、忠诚、保证、信仰等义，同形第三变格的 fidēs 是「弦琴」。"],["frangō","v.打碎","",""],["fābula","n.故事","",""],["fortitūdō","n.勇气","","Cicero 把它定义为「面对危险、忍受劳苦」的德性，是四主德之一的「勇」。"],["fragilis","adj.脆弱的","",""],["fulgor","n.光辉","","闪光、光芒；诗中也指闪电。"],["fāma","n.传闻|n.名声","|",""],["ferus","adj.野性的","","阴性名词 fera 指野兽。"],["fīnis","n.边界|n.尽头","|","复数 fīnēs 常指疆域、领土。；finem facere「结束」。"],["flamma","n.火焰","","诗中也比喻爱火。"],["furor","n.狂怒","","同形的 fūror 是「偷窃」义动词，不在本条。"]],"g":[["grandis","adj.大的","","常指成年的、大的；也指年迈、宏伟"],["gelidus","adj.寒冷的","","冰冷的，程度比 frīgidus 更强"],["generālis","adj.一般的","","亦罕见地指「类的」；非生物分类的「属」。"],["gelū","n.寒冷","","指严寒、霜冻；也指由死亡、年老、惊恐引起的寒意"],["grabattus","n.简陋床","","阳性名词；grabatus的双t异写，圣经与文学文本有据。"],["gēns","n.氏族|n.民族","|","罗马同姓的宗族，如 gēns Iūlia。；复数 gentēs 在教会拉丁里指外邦人。"],["gerō","v.进行","","bellum gerere 作战；rēs gestae 功业。本义「携带、穿戴」不在本条。"],["gladius","n.剑","",""],["gravis","adj.沉重的","","也引申为严重的、庄重的。"],["gaudeō","v.喜悦","","半异相动词（完成时用被动形式 gāvīsus sum），+奪格「因…而高兴」。"],["gemitus","n.呻吟","","L&S：a sigh, a groan, lamentation（Cic. Rosc. Am. 9,24；Verg. A. 1,485）"],["gurges","n.深渊","","本义是漩涡、汹涌深水，「深渊」为引申；比 barathrum 更偏水。"],["gaudium","n.喜悦","","指内心的喜悦，与外露的欢乐 laetitia 相对。"],["gignō","v.生育","","也指产生、造成。"],["glōria","n.荣耀","",""],["grātia","n.感激|n.恩宠","|","grātiās agere 道谢；grātiam referre 报恩。；教会拉丁指神的恩典。"],["grātus","adj.令人愉快的|adj.感激的","",""]],"h":[["homō","n.人","",""],["habeō","v.拥有|v.认为","","aliquem fidēlem habēre 认为某人可靠。"],["herī","adv.昨天","",""],["hiems","n.冬天|n.暴风雨（诗）","|","诗歌用法，如维吉尔 noctem hiememque ferēns。"],["hodiē","adv.今天","",""],["hōra","n.小时","","罗马的「小时」是白昼的十二分之一，随季节长短。"],["hostis","n.敌人","","古义是「外邦人」，常用义是「敌人」。"],["hūmānus","adj.人类的","","也指仁慈的、有教养的。"],["humus","n.地面","","阴性；处格 humī「在地上」。"],["historia","n.故事","","主义是历史；「故事」取其 II 义（一般叙述），书面。"],["honestus","adj.高尚的","","中性名词化 honestum 指「德行、正当」（西塞罗《论义务》）。"],["honor","n.荣誉","","西塞罗多写 honōs；复数常指官职。"],["hūmānī","n.凡人","","复数名词（hūmānī, -ōrum），意为人们、凡人；单数表「人」用 homō。"]],"i":[["imber","n.雨","","偏「骤雨、暴雨」；一般的雨是 pluvia。"],["incēdō","v.行走","","指庄重、从容地迈步，不同于一般的 ambulō"],["incubō","v.伏卧","","本义躺在、伏在其上；喻义「伏守财宝」带贬义，不是守护。"],["iuvō","v.帮助","","也有使愉快义"],["iam","adv.已经","",""],["ibī","adv.那里","",""],["imperium","n.命令|n.统治权","|","也指帝国、版图。"],["impetus","n.进攻","","也指冲劲、冲动。"],["incipiō","v.开始","","西塞罗只用现在时系统，完成时用 coepī。"],["ingenium","n.天性|n.才智","|",""],["ingēns","adj.巨大的","",""],["interdum","adv.有时","",""],["intereā","adv.其间","",""],["inveniō","v.找到","","也指发明、想出。"],["iterum","adv.再次","",""],["iugum","n.轭|n.山脊","|","也比喻奴役，sub iugum mittere「使降敌钻轭门」。"],["iūs","n.法律","","另有同形词 iūs「肉汤」，不在本条。"],["iuvenis","n.青年","","罗马人指约二十至四十岁的成年人。"],["iter","n.旅程","",""],["invideō","v.嫉妒","","与格带人：invidēre aliquī 嫉妒某人；另有「不肯给」义。"],["invidia","n.嫉妒","","也可指「招人嫉恨、众怒」；西塞罗常用 in invidiā esse 招人怨恨。"],["intereō","v.消亡","","intereō 指事物或人毁灭、不复存在，常见于「灭亡、死去」义。"],["interitus","n.毁灭","","也指人的夭亡。"],["invidus","adj.嫉妒的","","也指敌意的；作名词指嫉妒的人；+属格「嫉妒…」。"],["ignis","n.火","","诗里也指爱火、闪电、星光。"],["iniūria","n.不义","","iniūriā「无理地、冤枉地」。"],["īra","n.愤怒","",""]],"l":[["labor","n.辛劳","","名词（第三变格阳性）：费力的劳作；也指苦难、疲惫；与 lābor（滑行）长音有别"],["laetus","adj.快乐的","","也指丰饶的、茂盛的"],["legō","v.阅读","","本义聚拢、挑选，由此引出阅读"],["liber","n.书","","第二变格阳性；与 līber（自由的）同形，长音有别"],["lūna","n.月亮","",""],["līberī","n.孩子","","只用复数，指（一家的）子女、孩子们；同形 līber 是「自由的」，另一个词。"],["linquō","v.离开","","也指留下；linqui animo 指昏厥"],["langueō","v.疲倦","","也指衰弱、萎靡、花朵垂萎"],["lassus","adj.疲倦的","","多见诗歌与银拉丁；西塞罗、凯撒不用"],["lēctiō","n.阅读","","名词：阅读、朗读；也指挑选"],["lectus","n.床","","最通用的「床」，也指餐榻、婚床；lectus 的「读」义是另一个同形词。"],["lympha","n.水（诗）","","诗体词，指清水；日常用 aqua。"],["latex","n.水（诗）","","本义是液体，诗体常指水、泉水。"],["locūtiō","n.说话","","名词：说话；也指说话的方式、措辞"],["loquēla","n.说话","","名词：言语、话语；诗歌中常见"],["lingua","n.语言","","亦指舌头；方言义罕见。"],["latus","n.身侧","","形容词 lātus「宽的」与它同形，不在本条。"],["lēgātus","n.使节","","也指副将。"],["legiō","n.军团","",""],["lēx","n.法律","","也指规则、条件。"],["licet","v.被允许","","无人称动词：licet mihi 我可以；用作连词「尽管」不在本条。"],["līmen","n.门槛","","也喻家门、开端。"],["lītus","n.海岸","",""],["locus","n.地方","","复数有阳性 locī（书中段落）和中性 loca（地区）两种。"],["longus","adj.长的","","空间和时间都可用；nāvis longa 战舰。"],["lābor","v.滑落","","异相动词；也指时间流逝、犯错。"],["lūx","n.光","","指自然之光、白昼；也引申为生命、荣耀。"],["lūmen","n.光","","偏「光亮、光源」；与 lūx 比，lūmen 多指具体发光之物或眼光。"],["lībertās","n.自由","",""],["libīdō","n.欲望","","L&S：desire, fancy, inclination；多含任性、情欲色彩（Sall. Cic.）"],["līber","adj.自由的","","注意与 liber, librī（书）不同；līberī 复数是「子女」。"],["laetor","v.喜悦","","形式为被动的异相动词，意思是主动的「感到喜悦」，用奪格或 in/de 引出喜悦的事由。"],["lēnis","adj.温和的","",""],["licentia","n.自由","","指「被许可的自由」，常带放纵意味（英语 license）；与 lībertās 的政治自由不同。"],["līmes","n.边界","","本义是界路（可走的田埂），转指边界、界线；罗马帝国边防线也叫 līmes。"],["liquidus","adj.液态的","","也指清澈、明净。"],["lūctus","n.悲伤","","偏「哀悼、丧痛」，兼指丧服；与 dolor 不同，更含外显的哀悼。"],["lētum","n.死亡（诗）","","偏诗体、书面的「死」（常含暴死、毁灭）；散文里用 mors。"],["labyrinthus","n.迷宫","","尤指代达罗斯在克里特所建迷宫。"],["lacrima","n.眼泪","",""],["laus","n.赞美","",""]],"m":[["magnus","adj.大的","","比较级 māior，最高级 maximus"],["manus","n.手","","阴性第四变格；也指一队人、笔迹。"],["mare","n.海","",""],["mīles","n.士兵","","古典拉丁 mīles 即步兵/士兵，骑士用 eques。"],["malus","adj.坏的","","比较级 pēior，最高级 pessimus"],["mōns","n.山","",""],["mundus","adj.整洁的|n.世界","","形容词：整洁、雅致；与阳性名词 mundus（世界）同形；宇宙、天地；也指苍穹。"],["mēnsa","n.桌子","","也指饭桌上的一餐。"],["mantō","v.等待（古）","","古体动词，maneō的反复式；不及物等待，也可及物等待某人。"],["mēnsis","n.月份","","历法上的一个月；月亮是 lūna。"],["mandūcō","v.咀嚼","","口语中转指吃。"],["maritimus","adj.海的","","「海的、海上的、沿海的」。"],["mētior","v.测量","","异态动词；也指衡量、估量、走过一段路程"],["maleficus","adj.邪恶的","","指行为邪恶、作恶；也指施邪术的"],["māter","n.母亲","","也指源头、故乡。"],["membrum","n.肢体","",""],["mittō","v.派遣","","也指投掷、放走。"],["mora","n.延迟","","sine morā「立刻」。"],["mōs","n.习俗","","复数 mōrēs 常指品行、道德。"],["mox","adv.不久","",""],["multus","adj.许多的","","比较级 plūs、最高级 plūrimus。"],["mūnus","n.职责|n.礼物","|","复数 mūnera 也指角斗表演。"],["mūrus","n.城墙","",""],["mors","n.死亡","","也指尸体、毁灭。"],["morior","v.死亡","","异相动词，将来分词 moritūrus「将死的」；也指枯萎。"],["mollis","adj.柔和的","",""],["memoria","n.记忆","","也指回忆、纪念、历史记载。"],["maestus","adj.悲伤的","","比 tristis 更偏「悲痛、哀伤」。"],["maereō","v.悲伤","","偏书面、诗味的「哀伤、哀悼」；可及物「为…哀叹」。"],["micō","v.闪烁","","指一闪一闪、颤动着发光，也可指脉搏跳动。"],["misereō","v.怜悯","","+属格（misereor sociōrum 怜悯盟友）；古典时期多用异相形式 misereor。"],["misericordia","n.怜悯","","本义怜悯、同情；教会拉丁里多指「慈悲」，这里取古典义。"],["miseror","v.怜悯","","异相动词；本义「哀叹」，转为「怜悯」；Paul. ex Fest. 区分：miserātur 是哀叹，miserētur 是伸手相助。"],["mōmentum","n.瞬间","","本义「运动、推动力」，转为份量、关键的一点；「瞬间」多用奪格 momentō。"],["mūtus","adj.沉默的","","首义是「哑的、不能说话的」；「沉默的」是引申，指不出声。"],["maeror","n.悲伤","","较书面的「哀伤」，西塞罗定义为 aegritūdō flēbilis。"],["maestitia","n.悲伤","","比 tristitia 更偏「哀伤、沮丧」。"],["malevolus","adj.怀恶意的","","L&S：ill-disposed, spiteful, malevolent（Cic. Fam. 2,17,7；Att. 7,2,7）"],["marca","n.边境（教）","","中世纪拉丁；此处取传教书信的边境地域义，不是重量或货币单位。"],["mēns","n.心智","",""],["metus","n.恐惧","",""],["miser","adj.不幸的","","诗里常指为爱所苦的。"]],"n":[["nox","n.夜晚","","nox 就是夜、黑夜，与 diēs 相对。"],["novus","adj.新的","",""],["negōtium","n.工作","","更常指事务、公务、买卖；与 ōtium（闲暇）相对"],["nātūra","n.自然|n.天性","|","rērum nātūra「万物的本性」，卢克莱修诗题 Dē rērum nātūrā。"],["nāvis","n.船","",""],["nōlō","v.不愿","","nōlī + 不定式表示禁止：nōlī timēre「别怕」。"],["nōmen","n.名字","","罗马人名的第二部分（族名）也叫 nōmen。"],["numerus","n.数目","",""],["numquam","adv.从不","","也写 nunquam。"],["nunc","adv.现在","",""],["nusquam","adv.无处","",""],["nāscor","v.诞生","","异相动词，完成分词 nātus；也指「生出、产生」。"],["necessitās","n.必然","","不可避免之事；引申指命数。"],["nemus","n.树林","","多见于诗歌，常指圣林。"],["nūmen","n.神意","","也指神祇本身。"]],"o":[["oculus","n.眼睛","",""],["ops","n.帮助","","主格单数实际不出现（L&S），常见 opis、ope、opem；复数 opēs 指财富、实力"],["opus","n.工作","","名词（中性）：工作；也指作品、工程；opus est 表示需要"],["opera","n.工作","","强调出于自愿的劳力、效劳；与 opus 有别；opus 的复数 opera 另指作品"],["operor","v.工作","","异态动词；常与与格连用，意为致力于；诗歌与银拉丁常见"],["ōstium","n.门","","指门、入口；比 porta（城门）更偏屋门，也指河口。"],["ōstiārius","adj.门的（教）","","形容词义见于武加大译本（ancilla ostiaria 看门的使女）；常用的是名词 ōstiārius 守门人。"],["ōlim","adv.从前","","也可指将来的「有朝一日」。"],["omnis","adj.所有的","","单数多指「每个」，复数指「全部」；omnia 一切。"],["orbis","n.圆环|n.世界","|","多作 orbis terrārum；单用见于诗。"],["ōrdō","n.次序|n.阶层","|","ōrdine 依次、按顺序。；如元老阶层 ōrdō senātōrius、骑士阶层 ōrdō equester。"],["ōs","n.嘴","","另有同形词 os, ossis「骨头」，不在本条。"],["ostendō","v.展示","","也指表明、说明。"],["ōtium","n.闲暇","","与 negōtium（事务）相对；也指安宁、太平。"],["optō","v.希望","","偏「祝愿、盼望」（出于深思的愿望）。另有古/诗义「选择」，已另条列。"],["occidō","v.死亡","","这里取短 i 的 occidō（落下、倒下、死亡；日落）；与长 ī 的 occīdō（杀死）同形异义，易混。"],["obscūrus","adj.幽暗的","","也指晦涩、无名的。"],["oblīviō","n.遗忘","","指遗忘、被遗忘的状态；dare oblīviōnī 使被遗忘；也指大赦（本地列的 amnesty 义）。"],["oriēns","n.旭日","","oriēns 是升起的太阳，Verg. 常用；另有「东方」义（Cic.）。"],["odium","n.仇恨","",""],["orīgō","n.起源","","也指家世出身；加图的史书名 Origines。"],["ortus","n.日出","","常作 sōlis ortus；也指东方、出生。与 orior 的完成分词 ortus 同形。"]],"p":[["parvus","adj.小的","",""],["puer","n.男孩","","常用义是男孩、少年；也可指男童仆。"],["patria","n.祖国","","指故土、祖国；亦作故乡。"],["prōsum","v.帮助","","不规则动词（prodesse），与与格连用，侧重有益于"],["praesidium","n.保护","","也指守军、驻军、据点；与 auxilium（援助）有别"],["praebeō","v.给予","","本义伸出、递上，引申为提供、给予"],["pontus","n.海（诗）","","诗体色彩，指大海、深海。"],["porta","n.门","","多指城门、大门；屋门用 ōstium、forēs。"],["perpetuus","adj.不间断的","","DCC：unbroken, perpetual；L&S：continuous, uninterrupted（Cato R.R. 33；Cic. Pis. 22,51）"],["pānis","n.面包","","阳性第三变格。"],["paulus","adj.小的（古）","","形容词，L&S标早期及诗歌用法；不是专名Paulus，也不把paulum副词义混入。"],["pelagus","n.海","","希腊借词，诗体色彩，指大海、远海。"],["proficīscor","v.出发","","异态动词；指动身前往某地"],["pābulum","n.养料","","常指牲畜饲料；转义为精神的养料。"],["parvulus","adj.小的","","parvus 的指小形式，小小的、幼小的"],["paucus","adj.少数的","","几乎只用复数 pauci（少数人）、pauca（少数事物）"],["postis","n.门柱","","诗中以部分代整体指门。"],["prōlēs","n.孩子（诗）","","多为集合义，指后代、子孙，诗体色彩；表示「孩子」时不如 līberī、puer 日常。"],["pūbēs","n.青年男子","","L&S II.C：collect., grown-up males, youth, young men（Cic. Mil. 23,61；Verg. A. 5,573）"],["penus","n.食物","","指家中储存的食品、存粮；词的性数在古人笔下不稳定。"],["peregrīnātiō","n.旅行","","指旅居国外、游历；偏长途旅行，教会拉丁里的「朝圣」不取"],["problēma","n.问题","","借自希腊语，指待解的难题或论题；晚出（奥古斯都之后）"],["paene","adv.几乎","",""],["parēns","n.父母","","单数指父亲或母亲一方。"],["pars","n.部分","","也指一方、党派、角色。"],["pater","n.父亲","","复数 patrēs 也指元老。"],["pectus","n.胸膛","","也比喻心胸、心怀。"],["pecūnia","n.金钱","",""],["perīculum","n.危险","",""],["pēs","n.脚","",""],["petō","v.前往|v.请求","","直接带地名宾格：Rōmam petere 前往罗马。；petere ab aliquō 向某人请求。"],["poena","n.惩罚","","poenās dare「受罚」。"],["pōnō","v.放置","","castra pōnere 扎营。"],["populus","n.人民","","另有同形词 pōpulus「杨树」（阴性），不在本条。"],["possum","v.能够","","不规则动词，接不定式。"],["prīmus","adj.第一的","",""],["puella","n.女孩","","诗中常指情人。"],["procul","adv.在远方","",""],["pius","adj.虔敬的","","指对神、对亲人、对祖国的尽责与虔诚，如 pius Aeneas"],["persōna","n.面具","","演员的面具；引申为角色、人物。"],["placidus","adj.宁静的","",""],["paternus","adj.父亲的","","也指祖传的、故国的。"],["perennis","adj.永恒的","","偏「长年不断、持久不衰」（如泉水、纪念物），比 aeternus 弱；植物学「多年生的」。"],["persequor","v.追求","","本义「穷追、追随到底」；「追求」取其「谋求」义；另有「迫害、报复、执行」义。"],["profugus","adj.漂泊的","","首义是逃亡的、流亡的；「漂泊的」指四处游荡、居无定所（诗语）。"],["persevērantia","n.坚韧不拔","","指经过考虑后的持久坚持，褒义；近义的 pertinācia 偏「固执」。"],["polus","n.极点","","天轴的端点；诗中指苍穹。"],["pāx","n.和平","",""],["pellūcidus","adj.透明的","","也写作 perlūcidus。"],["pietās","n.虔敬","","对神、父母、祖国尽责的情感，维吉尔称埃涅阿斯 pius。"],["prex","n.祈祷","","单数主格不用，常用复数 precēs。"],["proelium","n.战斗","",""]],"q":[["quaerō","v.寻找","","也指询问、谋求"],["quantus","adj.多大的","","疑问、感叹或与 tantus 呼应。"],["quondam","adv.昔日","",""],["quiēs","n.安宁","","休息、宁静；也指睡眠。"],["queror","v.抱怨","","异相动词；诗里也指鸟兽哀鸣。"]],"r":[["relinquō","v.抛弃","","也指留下、遗留；「离开」另用 discēdō、abeō"],["referō","v.带回","","不规则动词；也指汇报、归还、追溯到"],["respondeō","v.回答","","也指相符、对应"],["recēdō","v.离开","","本义后退、退开，由此引申退离、离开"],["requīrō","v.寻找","","也指询问、需要、思念"],["recēns","adj.新的","","强调刚发生、新鲜的，与 novus（新的）有别"],["remedium","n.补救办法","","也指药物、疗法"],["rapiō","v.抢夺","",""],["recipiō","v.收回","","sē recipere 撤退；也指接纳。"],["reddō","v.归还","","也指「使成为」（reddere + 双宾格）。"],["rēgnum","n.王国","","也指王权、统治。"],["rēs","n.事物","","含义极广，随语境译「事情、东西、财产」；rēs pūblica 国家。"],["rēx","n.国王","","共和时期带贬义，指专制者。"],["rūrsus","adv.重新","",""],["redeō","v.归来","",""],["regiō","n.边界","","常义是「地区、方向」；「边界」指视线或占卜划出的界线，用于梗图时慎用。"],["resistō","v.抵抗","","常接与格；另有本义「停住、站住」。"],["restō","v.留下","","也指抵住、剩余。"],["refrāgor","v.抵抗","","偏「反对、阻挠」（本为公民投票上的反对）；比 resistō 更偏言论与政治抵制。"],["reditus","n.归来","","另有「收益」义，不在本条。"],["renāscor","v.重生","","异态动词，形式被动、意义主动。"]],"s":[["sum","v.是","","最基本的系动词；也表示存在：cōgitō ergō sum「我思故我在」。"],["sōlus","adj.唯一的","","DCC：only, alone；L&S：alone, sole, only（Cic. Cat. 4,7,14）"],["sōl","n.太阳","",""],["somnus","n.睡眠","",""],["studium","n.热忱","","也指好感、偏爱；复数 studia 指学业"],["spīritus","n.呼吸","","本义是呼吸、气息；引申为生命、精神。"],["sēnsus","n.感觉","","指感官感受、知觉。"],["studeō","v.热衷","","与与格连用，指热心于、致力于某事；后期才有「读书求学」义"],["spīrō","v.呼吸","","本义是呼吸、吹气；现分词 spirans 常表「活着」；引申有「散发气味」「吐露」。"],["salum","n.海","","多见单数的第四、第五格，指远离海岸的外海、深海。"],["sitiō","v.口渴","","转指渴求：sanguinem sitire。"],["sodālis","n.朋友","","偏「同伴、伙伴、密友」，也指社团成员；可与 amīcus 并用（amicus et sodalis）。"],["sopor","n.睡眠","","偏「沉睡、酣睡」，诗体色彩；日常的「睡眠」用 somnus。"],["subveniō","v.帮助","","与与格连用；本义是上前援助，也指想起"],["succurrō","v.帮助","","与与格连用；本义是跑去救援"],["sponda","n.床","","诗体偏多，本义是床架，泛指床、榻。"],["saepe","adv.经常","",""],["sanguis","n.血","","也指血统、后裔。"],["saxum","n.岩石","",""],["sciō","v.知道","",""],["scrīptiō","n.写作","","指写作、撰述这件事；L&S 注「几乎只见于西塞罗」。"],["sēdēs","n.座位|n.居所","|",""],["semper","adv.总是","",""],["sequor","v.跟随","","异相动词。"],["servus","n.奴隶","",""],["signum","n.记号|n.军旗","|","signa ferre「拔营进军」。"],["silva","n.森林","",""],["simul","adv.同时","",""],["sinus","n.怀抱|n.海湾","|",""],["soror","n.姐妹","",""],["spatium","n.空间","","也指一段时间。"],["statim","adv.立刻","",""],["spēs","n.希望","",""],["sors","n.命运","","本义是签、抽签；引申为命运、神谕。"],["spērō","v.希望","",""],["serēnus","adj.宁静的","","首义是「晴朗的」（天），转指心境平静。"],["silentium","n.沉默","",""],["somnium","n.梦","",""],["sector","v.追求","","本义「紧随、跟班」；追求义见 Plaut.、Caes.、Hor. 等。同形名词 sector（割取者、拍卖买主）不是本义。"],["sīdereus","adj.星辰的（诗）","","诗语，如 caelum sīdereum（星空）。"],["sileō","v.沉默","","比 taceō 更强，指连声响也没有（也可指「不提及」）。"],["sōlitārius","adj.孤独的","","偏「独自的、独居的」，不一定带寂寞情绪；比 sōlus 更像「离群的」。"],["sōlitūdō","n.孤独","","也指荒僻之地、无人的状态；孤独感与「荒无人烟」两义并用。"],["subsistō","v.停住","","也指站稳、顶住。"],["sempiternus","adj.永恒的","","「永远存在的」，比 aeternus 更重持续到时间尽头。"],["sequāx","adj.紧追的（诗）","","sequāx 指紧跟着追赶，诗语（Verg.）；另有「易弯曲的」义。"],["scelus","n.罪行","","语气最重的「罪恶」；口语里也骂人「坏蛋」。"],["sīdus","n.星辰","",""]],"t":[["tepeō","v.温暖（罕）","","指微温，程度比 caleō 弱；较罕用"],["tālis","adj.这样的","","常与 quālis 呼应。"],["tandem","adv.终于","",""],["tantus","adj.这么大的","","常与 quantus 呼应：tantus … quantus「和……一样大」。"],["tēctum","n.屋顶|n.房屋","|",""],["templum","n.神庙","","本义是鸟卜划定的观测区。"],["teneō","v.握住","","也指占据、保持、记住。"],["tergum","n.背部","","terga vertere「转身逃跑」。"],["terra","n.大地","","也指陆地、土壤、国土。"],["trahō","v.拖","","也指吸引、拖延。"],["tum","adv.那时","",""],["tunc","adv.当时","","比 tum 更强调。"],["turba","n.骚乱|n.人群","|",""],["trīstis","adj.悲伤的","","也指严厉、阴沉，和味道苦涩。"],["taceō","v.沉默","",""],["taedium","n.厌倦","","常与属格连用，指对某事的厌烦；晚出（奥古斯都之后）"],["terminus","n.边界","","本义是界石、界标，也指终点、限度；现代英语 terminus 即由此来。"],["trīstitia","n.悲伤","","比 maestitia 更常用于一般的忧郁情绪；亦指（语气）严厉。"],["tūtēla","n.守护","","偏「看护、保护、监护」；tūtēla 也指守护神或被监护关系。"],["tēlum","n.投射兵器","","泛指刀剑等进攻兵器时也用。"],["tempus","n.时间","","另有同形词 tempus「太阳穴」（多用复数 tempora），不在本条。"],["timeō","v.害怕","","timeō nē … 「怕会……」。"],["timor","n.恐惧","",""]],"u":[["urbs","n.城市","","大写 Urbs 特指罗马城。"],["ubīque","adv.到处","",""],["umquam","adv.曾经","","多用于否定句、疑问句和条件句。"],["ūnus","adj.唯一的","","本义「一」，数词用法不在本条。"],["ūtor","v.使用","","异相动词，宾语用夺格。"],["unda","n.波浪","","诗中泛指水、海。"],["umbra","n.影子","",""]],"v":[["videō","v.看见","",""],["veniō","v.来到","",""],["ventus","n.风","",""],["vetus","adj.旧的","",""],["voluptās","n.快乐","","偏重感官与精神的快乐，伊壁鸠鲁学派用语"],["vādō","v.行走","","偏重急行、径直前往，比 ambulō 更急"],["vadum","n.浅滩","","可涉水而过之处；诗中泛指水域。"],["vapor","n.蒸气","","也指热气、暖意"],["vīctus","n.食物","","指维持生活的食物、饮食、生计；同形 victus 作 vincō 的分词是「被征服」。"],["vēr","n.春天","","vēre novō「新春时节」（维吉尔）。"],["verbum","n.词语","",""],["vestis","n.衣服","",""],["via","n.道路|n.方法","|","如 via vivendi 生活方式。"],["victor","n.胜利者","",""],["vir","n.男人|n.丈夫","|","有「真男子、勇士」的意味，与泛指「人」的 homō 不同。"],["virgō","n.少女","",""],["vīs","n.力量|n.暴力","|","复数 vīrēs 多指体力、兵力。单数 vīs 与 volō 的「你想要」同形。；vim afferre 施暴。"],["vitium","n.缺陷","","也指道德上的恶习。"],["vix","adv.勉强","",""],["vōx","n.声音","",""],["vulnus","n.伤口","",""],["vultus","n.面容","",""],["volō","v.希望","","更准确是「想要、愿意」；「希望」取其「想要某事发生」之义。与 spērō（期待）不同。"],["vīta","n.生命","","也指生活方式、生平、传记。"],["virtūs","n.勇气","","本义是男子气概，转指勇气、德行。"],["vīsiō","n.幻象","","本义是看见、视觉；「幻象」取其「所见的显象」义，Cicero 用来指外来的映象。"],["vīsum","n.幻象","","本义是「所见之物、景象」，visa somniōrum 即梦中所见的幻象；在哲学语境里译 φαντασία（印象）。"],["vēnor","v.狩猎","","异相动词；转指追逐、谋求。"],["vītālis","adj.生命的","","「生命的、维持生命的」，如 calor vitālis 生命之热。"],["vēlificor","v.扬帆","","异相动词；转指全力以赴。"],["vēritās","n.真理","",""],["vincō","v.战胜","","名句 vēnī, vīdī, vīcī；omnia vincit amor（维吉尔）。"],["vīvō","v.活着","","也指生活、过日子。"],["vōtum","n.誓愿","",""]],"z":[["zōna","n.腰带","","尤指女子的束腰带，zōnam solvere 解带（指成婚）；另指钱袋腰带、地球的气候带，不在本条。"],["zēlus","n.热忱（教）","","教会拉丁语；希腊借词；名句 zelus domus tuae comedit me（武加大译本 Ps. 68,10、Ioh. 2,17）。古典作家多指嫉妒、竞争心，不在本条。"],["zephyrus","n.西风","","指和煦的春季西风，本族词是 favōnius；拟人即西风神 Zephyrus。"]]});
